const CIDR = {{cidr}};
const ip = [192, 168, 3, 77];
const bits = ip.map((o) => o.toString(2).padStart(8, '0')).join('');
const net = bits.slice(0, CIDR).padEnd(32, '0');
const bc = bits.slice(0, CIDR).padEnd(32, '1');
const toIp = (s) => [0, 1, 2, 3].map((i) => parseInt(s.slice(i * 8, i * 8 + 8), 2)).join('.');
ctx.clearRect(0, 0, W(), H());
ctx.font = '14px ui-monospace, monospace';
bits.split('').forEach((b, i) => {
  ctx.fillStyle = i < CIDR ? '#60a5fa' : '#374151';
  ctx.fillRect(14 + i * 11, 26, 9, 18);
});
ctx.fillStyle = '#eee'; ctx.font = '14px system-ui';
ctx.fillText('주소 ' + ip.join('.') + '/' + CIDR, 14, 20);
ctx.fillText('네트워크 ' + toIp(net) + '  ~  ' + toIp(bc), 14, 70);
ctx.fillStyle = '#9ca3af'; ctx.font = '13px system-ui';
ctx.fillText('쓸 수 있는 주소 ' + Math.max(0, 2 ** (32 - CIDR) - 2).toLocaleString() + '개 (파랑 = 고정 부분)', 14, 96);
